INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7615, 2767, 'tt0101318', NULL, 'The Lovers on the Bridge', 'Les Amants du Pont-Neuf', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/un81oln6mAv66sqnkgPSpWONUqP.jpg', 'https://image.tmdb.org/t/p/original/6vWdQxx4yqV5kEeAqtzBHndo3Eg.jpg', 'Set against Paris'' oldest bridge, the Pont Neuf, while it was closed for repairs, this film is a love story between two young vagrants: Alex, a would be circus performer addicted to alcohol and sedatives and Michele, a painter driven to a life on the streets because of a failed relationship and an affliction which is slowly turning her blind.', NULL, NULL, 2.6518, 7.4, 0, 21.02, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7616, 338969, 'tt1633359', NULL, 'The Toxic Avenger Unrated', 'The Toxic Avenger Unrated', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/cCWojb6N9UcTzNVtS4bOM3vQ30x.jpg', 'https://image.tmdb.org/t/p/original/qo7WRoSXkpgvmc9TgaklzrsukLW.jpg', 'When a downtrodden janitor, Winston Gooze, is exposed to a catastrophic toxic accident, he’s transformed into a new kind of hero: The Toxic Avenger. Now, Toxie must rise from outcast to savior, taking on ruthless corporate overlords and corrupt forces who threaten his son, his friends, and his community.', NULL, NULL, 7.3262, 5.965, 0, 51.05, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7617, 10229, 'tt0281358', NULL, 'A Walk to Remember', 'A Walk to Remember', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/8lUYMvWdHA0Q0k5F76RQCeCBUkA.jpg', 'https://image.tmdb.org/t/p/original/uRdJx2p950EobLYuf7Oz39Wk7jd.jpg', 'When the popular, restless Landon Carter is forced to participate in the school drama production, he falls in love with Jamie Sullivan, the daughter of the town''s minister. Jamie has a "to-do" list for her life, as well as a very big secret she must keep from Landon.', NULL, NULL, 6.1089, 7.751, 0, 21.02, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7618, 337167, 'tt4477536', NULL, 'Fifty Shades Freed', 'Fifty Shades Freed', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/jjPJ4s3DWZZvI4vw8Xfi4Vqa1Q8.jpg', 'https://image.tmdb.org/t/p/original/9ywA15OAiwjSTvg3cBs9B7kOCBF.jpg', 'Believing they have left behind shadowy figures from their past, newlyweds Christian and Ana fully embrace an inextricable connection and shared life of luxury. But just as she steps into her role as Mrs. Grey and he relaxes into an unfamiliar stability, new threats could jeopardize their happy ending before it even begins.', NULL, NULL, 21.7978, 6.7, 0, 11.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7619, 56568, 'tt0810705', NULL, 'NANA', 'NANA', 'tv', 2006, 'https://image.tmdb.org/t/p/w500/egEROVWFVUupRhK03Bj5IVGAEGu.jpg', 'https://image.tmdb.org/t/p/original/oDjjcXWIWBbeb6hDE28y4LpTaJd.jpg', 'Nana Osaki and Nana Komatsu meet while traveling to Tokyo in pursuit of their respective dreams, and decide to be roommates. Although drastically different people, the two become very close and together they find out if their biggest dreams have room for their best friend.', NULL, NULL, 21.4876, 8.492, 0, 2.2009999999999998e+01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7620, 82596, 'tt8962124', NULL, 'Emily in Paris', 'Emily in Paris', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/c0bkO416OU7YGdOFktk45H8REgL.jpg', 'https://image.tmdb.org/t/p/original/jXTZaHarR9TZiMoQwiQWsGYXqnS.jpg', 'New passions. New fashions. New Emily? A plucky American marketing whiz spreads her wings in life and love after landing her dream job in Paris.', NULL, NULL, 24.5005, 7.6, 0, 1.0, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
