INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7622, 27103, 'tt0119590', NULL, 'My Life in Pink', 'Ma vie en rose', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/4SwZaSDy1DR80QXKdvp6iSTawK2.jpg', 'https://image.tmdb.org/t/p/original/nfj0CWrBw6lRjPb1yUSqxGjgudt.jpg', 'Ludovic is waiting for a miracle. With six-year-old certainty, she believes she was meant to be a little girl -- and that the mistake will soon be corrected. But where she expects the miraculous, Ludo finds only rejection, isolation, and guilt -- as the intense reactions of family, friends, and neighbors strip away every innocent lace and bauble.', NULL, NULL, 1.2436, 6.8, 0, 1.02, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
