INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7630, 26782, 'tt0058642', NULL, 'Shadows of Forgotten Ancestors', 'Тіні забутих предків', 'movie', 1965, 'https://image.tmdb.org/t/p/w500/9oSZTeejmx80tIBVSqYzJpFhjkI.jpg', 'https://image.tmdb.org/t/p/original/9UQoFWYiNU1NIz7pQlg5Wnub9In.jpg', 'In the Carpathian Mountains of 19th-century Ukraine, love, hate, life and death among the Hutsul people are as they’ve been since time began. Ivan is drawn to Marichka, the beautiful young daughter of the man who killed his father. But fate tragically decrees that the two lovers will remain apart.', NULL, NULL, 2.0244, 7.535, 0, 1.05, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7631, 1631917, 'tt39751309', NULL, '18th Rose', '18th Rose', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/6pUwaXT6tdA6sek8o6SdFYudJDj.jpg', 'https://image.tmdb.org/t/p/original/21YKck5bSRcvRIXlVg6ZaV0k0sj.jpg', 'A spirited teen dreaming of the perfect debut makes a deal with a lonely newcomer, but unexpected feelings and revelations may shatter their plans.', NULL, NULL, 5.0114, 7.7, 0, 1.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7632, 780, 'tt0019254', NULL, 'The Passion of Joan of Arc', 'La Passion de Jeanne d''Arc', 'movie', 1928, 'https://image.tmdb.org/t/p/w500/tAgV9yxY6AC1bsPt3qJJQpD4s8.jpg', 'https://image.tmdb.org/t/p/original/cFgCf2XqnhErS3HmgSOBCe4kL4d.jpg', 'A classic of the silent age, this film tells the story of the doomed but ultimately canonized 15th-century teenage warrior. On trial for claiming she''d spoken to God, Jeanne d''Arc is subjected to inhumane treatment and scare tactics at the hands of church court officials. Initially bullied into changing her story, Jeanne eventually opts for what she sees as the truth. Her punishment, a famously brutal execution, earns her perpetual martyrdom.', NULL, NULL, 3.1078, 8.0, 0, 1.1, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7633, 583, 'tt0079470', NULL, 'Life of Brian', 'Life of Brian', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/lSSA64WF0M0BXnjwr2quMh6shCl.jpg', 'https://image.tmdb.org/t/p/original/lOrM3OQhHlzEkpF7Ih3GghecrA8.jpg', 'Brian Cohen is an average young Jewish man, but through a series of ridiculous events, he gains a reputation as the Messiah. When he''s not dodging his followers or being scolded by his shrill mother, the hapless Brian has to contend with the pompous Pontius Pilate and acronym-obsessed members of a separatist movement. Rife with Monty Python''s signature absurdity, the tale finds Brian''s life paralleling Biblical lore, albeit with many more laughs.', NULL, NULL, 8.7815, 7.761, 0, 1.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7634, 1029955, 'tt22408160', NULL, 'Kinds of Kindness', 'Kinds of Kindness', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/50lPmjIpDs8gKfgK7fPIeKzpllh.jpg', 'https://image.tmdb.org/t/p/original/aX1P75MWK5BzjqPh8fR8HQoX27s.jpg', 'A triptych fable following a man without choice who tries to take control of his own life; a policeman who is alarmed that his wife who was missing-at-sea has returned and seems a different person; and a woman determined to find a specific someone with a special ability, who is destined to become a prodigious spiritual leader.', NULL, NULL, 6.8469, 6.482, 0, 1.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7635, 12545, 'tt0070239', NULL, 'Jesus Christ Superstar', 'Jesus Christ Superstar', 'movie', 1973, 'https://image.tmdb.org/t/p/w500/2NQgIjHxYyMJZWeUFH5cuKhN4nh.jpg', 'https://image.tmdb.org/t/p/original/xQRh7hSPdtEE0aUmuY8EdifrXPK.jpg', 'As played out by a theatre troupe, the last days of Jesus Christ are depicted from the perspective of Judas Iscariot, his betrayer. As Jesus'' following increases, Judas begins to worry that Jesus is falling for his own hype, forgetting the principles of his teachings and growing too close to the prostitute Mary Magdalene.', NULL, NULL, 3.8713, 7.1, 0, 1.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7636, 748368, 'tt3311444', NULL, 'Sir Lanval', 'Sir Lanval', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/lbcud2jnANTTCxRtUAy5iVxZiZm.jpg', 'https://image.tmdb.org/t/p/original/iKwvt0ma6SgI2q4APWzmFWOmAOm.jpg', 'A stranger arrives at King Arthur''s Court of Camelot hoping to become a knight, only to be disillusioned. But a mysterious fairy maiden takes him as her lover, giving magical gifts which attract the attention of a jealous Queen Guinevere.', NULL, NULL, 0.6329, 8.0, 0, 10.03, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7637, 839033, 'tt14824600', NULL, 'The Lord of the Rings: The War of the Rohirrim', 'The Lord of the Rings: The War of the Rohirrim', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/23WCoDo6wzBfzbX7BGTNwVUqZfi.jpg', 'https://image.tmdb.org/t/p/original/ie8OSgIHEl6yQiGJ90dsyBWOpQA.jpg', 'A sudden attack by Wulf, a clever and traitorous lord of Rohan seeking vengeance for the death of his father, forces Helm Hammerhand, the King of Rohan, and his people to make a daring last stand in the ancient stronghold of the Hornburg.', NULL, NULL, 9.25, 6.553, 0, 9.02, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7638, 209867, 'tt22248376', NULL, 'Frieren: Beyond Journey''s End', '葬送のフリーレン', 'tv', 2023, 'https://image.tmdb.org/t/p/w500/dqZENchTd7lp5zht7BdlqM7RBhD.jpg', 'https://image.tmdb.org/t/p/original/rBOnrVlck7BIlGeWVlzYiZeg4l2.jpg', 'After the party of heroes defeated the Demon King, they restored peace to the land and returned to lives of solitude.  Generations pass, and the elven mage Frieren comes face to face with humanity’s mortality. She takes on a new apprentice and promises to fulfill old friends’ dying wishes. Can an elven mind make peace with the nature of life and death? Frieren embarks on her quest to find out.', NULL, NULL, 80.6247, 8.802, 0, 6.51, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7639, 311291, 'tt3544082', NULL, '45 Years', '45 Years', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/8elIJYYXWq2HpcZ6TgVMC9EwTnn.jpg', 'https://image.tmdb.org/t/p/original/nfISD7hILE6UYqXGT1cubcgsxUA.jpg', 'There is just one week until Kate Mercer''s 45th wedding anniversary and the planning for the party is going well. But then a letter arrives for her husband. The body of his first love has been discovered, frozen and preserved in the icy glaciers of the Swiss Alps. By the time the party is upon them, five days later, there may not be a marriage left to celebrate.', NULL, NULL, 3.359, 6.6, 0, 10.03, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7640, 49046, 'tt1016150', NULL, 'All Quiet on the Western Front', 'Im Westen nichts Neues', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/2IRjbi9cADuDMKmHdLK7LaqQDKA.jpg', 'https://image.tmdb.org/t/p/original/xBwtP27cx8WfjHJVFkpuV6F1RES.jpg', 'Paul Baumer and his friends Albert and Muller, egged on by romantic dreams of heroism, voluntarily enlist in the German army. Full of excitement and patriotic fervour, the boys enthusiastically march into a war they believe in. But once on the Western Front, they discover the soul-destroying horror of World War I.', NULL, NULL, 14.9676, 7.739, 0, 10.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7641, 847143, 'tt15028452', NULL, 'Baby Assassins', 'ベイビーわるきゅーれ', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/4A3hk4sT4EETeu7XqbLKFDFtFFu.jpg', 'https://image.tmdb.org/t/p/original/zVkfZ8Wa7u9zKHsKujv95Kjlpez.jpg', 'Two high school girls who are about to graduate also happen to be highly-skilled assassins. When the organization they work for orders them to share a room, their relationship quickly sours. But when they become targets of the yakuza, the girls realize they''ll have to work together to survive.', NULL, NULL, 1.876, 6.616, 0, 10.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7642, 13889, 'tt0107474', NULL, 'Madadayo', 'まあだだよ', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/d6uufygMy6kUwuNgIjtmSIomqzM.jpg', 'https://image.tmdb.org/t/p/original/osYVAYoyJbL0BySa61cMyMkgUvN.jpg', 'In postwar Tokyo, beloved writer-professor Hyakken Uchida retires and is buoyed through hardship by the fierce devotion of his former students, who honor him each year with a raucous “Not yet!” birthday toast. Told in warm, gently comic vignettes, Kurosawa’s farewell celebrates aging, friendship, and the sustaining ritual of teacher and pupils refusing to say goodbye.', NULL, NULL, 1.7582, 7.342, 0, 10.53, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7643, 1432547, 'tt36148135', NULL, 'ALL YOU NEED IS KILL', 'ALL YOU NEED IS KILL', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/kznh3ACnXYVyyAYes7JN6i1wy2d.jpg', 'https://image.tmdb.org/t/p/original/c2UTBDLSIFgxlz4XdjSooNGrMXb.jpg', 'When a massive alien flower known as "Darol" unexpectedly erupts in a deadly event, unleashing monstrous creatures that decimate the population of Japan, Rita is caught in the destruction—and killed. But then she wakes up again. And again. Caught in an endless time loop, Rita must navigate the trauma and repetition of death until she crosses paths with Keiji, a shy young man trapped in the same cycle. Together, they fight to break free from the loop and find meaning in the chaos around them.', NULL, NULL, 4.3802, 6.4, 0, 9.02, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
