INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7651, 51120, 'tt0054176', NULL, 'Peter Pan', 'Peter Pan', 'movie', 1960, 'https://image.tmdb.org/t/p/w500/qCQ42aTmU4cuHwzfu8rCvYQuCyx.jpg', 'https://image.tmdb.org/t/p/original/wxABOG4X5wvdt0fYggKE3gGWfGh.jpg', 'In this magical tale about the boy who refuses to grow up, Peter Pan and his mischievous fairy sidekick Tinkerbell visit the nursery of Wendy, Michael and John Darling. With a sprinkling of pixie dust, Peter and his new friends fly out the nursery window and over London to Never-Never Land. The children experience many wonderful and exciting adventures with the Lost Boys, Tiger Lily''s Indian tribe, and Peter''s arch enemy the dastardly pirate Captain Hook.', NULL, NULL, 1.0303, 6.7, 0, 1.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
