INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7654, 11049, 'tt0368667', NULL, 'Interstella 5555: The 5tory of the 5ecret 5tar 5ystem', 'Interstella 5555: The 5tory of the 5ecret 5tar 5ystem', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/n0K6mjU8aVnag2mi93FuvJsjZi.jpg', 'https://image.tmdb.org/t/p/original/eDso5UEr3nnA1SYPH3aVDsjE09I.jpg', 'Four talented alien musicians are kidnapped by a record producer who disguises them as humans. Shep, a space pilot in love with bass player Stella, follows them to Earth. Reprogrammed to forget their real identities and renamed The Crescendolls, the group quickly becomes a huge success playing soulless corporate pop. At a concert, Shep manages to free all the musicians except Stella, and the band sets out to rediscover who they really are — and to rescue Stella.', NULL, NULL, 2.4764, 7.809, 0, 1.02, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
