INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7656, NULL, NULL, 10148, 'Night in the Woods', 'Night in the Woods', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ovg.jpg', NULL, 'Night In The Woods is an adventure game heavily focused on story, characters and exploration, with some platforming to get around town. Mae''s a cat so the roofs and ledges and powerlines are all her playground, and she''s not the only one up there by a long shot. You''ll also be doing various activities and interacting with the world in different ways, getting to know the townspeople, hanging out with friends, exploring Possum Springs inside and out, and venturing into the surrounding areas.', 'https://www.igdb.com/games/night-in-the-woods', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 1.02, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
