INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7680, 1359, 'tt1002739', NULL, 'The Real Wedding Crashers', 'The Real Wedding Crashers', 'tv', 2007, NULL, NULL, 'The Real Wedding Crashers is an American prank/hidden camera series on NBC, inspired by the 2005 film Wedding Crashers, that premiered on April 23, 2007.

The series was produced by Ashton Kutcher, Karey Burke, Rich Meehan, Jon Kroll, Jim Rosenthal and Jason Goldberg with RDF USA, the production company of shows like Wife Swap, in association with New Line Television, part of the studio that produced the film. No one among the show''s main cast and crew were involved in the original film, nor were the cast and crew of the film involved with the series.

It was announced on May 7, 2007, that the series would be pulled after three episodes. NBC subsequently announced on its website that a fourth episode would air on May 28, 2007. NBC announced on July 20, 2007 that the show was not renewed. The two episodes not aired on NBC have subsequently aired on the Style Network.', NULL, NULL, 1.2847, 3.0, 0, 8.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7681, 10030, 'tt0452625', NULL, 'Good Luck Chuck', 'Good Luck Chuck', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/b2VgUoXR9iAtAf8nA0mvdTr7cOt.jpg', 'https://image.tmdb.org/t/p/original/5R4kLw5lxeiwX5hZfspK3YLg6wp.jpg', 'Cursed since childhood, dentist Charlie Logan cannot find the right woman. Even worse, he learns that each of his ex-girlfriends finds true love with the man she meets after her relationship with him ends. Hearing of Charlie''s reputation as a good-luck charm, women from all over line up for a quick tryst. But when Charlie meets the woman of his dreams, he must find a way to break the curse or risk losing her to the next man she meets.', NULL, NULL, 7.5511, 5.935, 0, 8.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7682, 332, 'tt0141369', NULL, 'Inspector Gadget', 'Inspector Gadget', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/dDcsv1Lql5aM6H4JYfDHjBAXKgT.jpg', 'https://image.tmdb.org/t/p/original/7OsGo8yVkTgD1ZJMBi9M8GP5aes.jpg', 'John Brown is a bumbling but well-intentioned security guard who is badly injured in an explosion planned by an evil mastermind. He is taken to a laboratory, where Brenda, a leading robotics surgeon, replaces his damaged limbs with state-of-the-art gadgets and tools. Named "Inspector Gadget" by the press, John -- along with his niece, Penny, and her trusty dog, Brain -- uses his new powers to discover who was behind the explosion.', NULL, NULL, 5.3404, 4.5, 0, 1.18, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
