INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7712, 996933, 'tt21226876', NULL, 'Piaffe', 'Piaffe', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/kYTb4rnjBMLUoxjUbgaT3DB5eHw.jpg', 'https://image.tmdb.org/t/p/original/mXmMXlTIc8xOxtSB0tbHZoM1coo.jpg', 'When her sibling Zara suffers a nervous breakdown, the introvert Eva is forced to take on Zara’s job as a Foley artist. She struggles to create sounds for a commercial featuring a horse, and then a horsetail starts growing out of her body. Empowered by her tail, she lures a botanist into an affair, through a game of submission. Piaffe is a visceral journey into control, gender, and artifice.', NULL, NULL, 1.5996, 4.5, 0, 1.03, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
