INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7717, 32489, 'tt0062362', NULL, 'Thoroughly Modern Millie', 'Thoroughly Modern Millie', 'movie', 1967, 'https://image.tmdb.org/t/p/w500/ce8rBGFR0naGsp6mKy9CNKn9iSa.jpg', 'https://image.tmdb.org/t/p/original/ufekY2p0zR41eAeKDrqpmylDa6K.jpg', 'Millie Dillmount, a fearless young lady fresh from Salina, Kansas, determined to experience Life, sets out to see the world in the rip-roaring Twenties. With high spirits and wearing one of those new high hemlines, she arrives in New York to test the "modern" ideas she had been reading about back in Kansas: "I''ve taken the girl out of Kansas. Now I have to take Kansas out of the girl!"', NULL, NULL, 1.9902, 6.866, 0, 1.07, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
