INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7719, 43078, 'tt1988386', NULL, 'Miss Fisher''s Murder Mysteries', 'Miss Fisher''s Murder Mysteries', 'tv', 2012, 'https://image.tmdb.org/t/p/w500/AeHJVpoWWKtCyFIZ6LbLkAR52vz.jpg', 'https://image.tmdb.org/t/p/original/hX3IxzUc6EUh0PG1mCpCfnuK7ul.jpg', 'Our lady sleuth sashays through the back lanes and jazz clubs of late 1920’s Melbourne, fighting injustice with her pearl handled pistol and her dagger sharp wit. Leaving a trail of admirers in her wake, our thoroughly modern heroine makes sure she enjoys every moment of her lucky life. Based on author Kerry Greenwood''s Phryne Fisher Murder Mystery novels.', NULL, NULL, 12.2765, 7.656, 0, 2.035, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7720, 306819, 'tt0810819', NULL, 'The Danish Girl', 'The Danish Girl', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/mXZZIacI5FC8thzSC0lgQBQ2uAX.jpg', 'https://image.tmdb.org/t/p/original/d0tzLbn62WANaq5mnyLpCJsJq1B.jpg', 'When Gerda Wegener asks her husband Einar to fill in as a portrait model, Einar discovers the person she''s meant to be and begins living her life as Lili Elbe. Having realized her true self and with Gerda''s love and support, Lili embarks on a groundbreaking journey as a transgender pioneer.', NULL, NULL, 6.4363, 7.542, 0, 1.29, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7721, 41971, 'tt0095649', NULL, 'The Moderns', 'The Moderns', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/7ENbrVNqcoCJqyqfyoFv1ox08fC.jpg', 'https://image.tmdb.org/t/p/original/e0tGFtNYjv0rUZtFuwlixDRauJs.jpg', 'Nick Hart is a struggling American artist who lives amongst the expatriate community in 1920s Paris. He spends most of his time drinking and socializing in local café''s and pestering gallery owner Libby Valentin to sell his paintings. He becomes involved in a plot by wealthy art patroness Nathalie de Ville to forge three paintings. This leads to several run-ins with American rubber magnate Bertram Stone, who happens to be married to Hart''s ex-wife Rachel.', NULL, NULL, 1.8184, 5.926, 0, 2.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
