INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7723, 15739, 'tt0083564', NULL, 'Annie', 'Annie', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/xopqD99S1GqQOG8UAeSElsX9MeP.jpg', 'https://image.tmdb.org/t/p/original/uP8eElA1j4I2lE0V67bhQaUipkc.jpg', 'An orphan in a facility run by the mean Miss Hannigan, Annie believes that her parents left her there by mistake. When a rich man named Oliver "Daddy" Warbucks decides to let an orphan live at his home to promote his image, Annie is selected. While Annie gets accustomed to living in Warbucks'' mansion, she still longs to meet her parents. So Warbucks announces a search for them and a reward, which brings out many frauds.', NULL, NULL, 4.646, 6.559, 0, 1.01, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
