INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7725, 64506, 'tt4878612', NULL, 'Z: The Beginning of Everything', 'Z: The Beginning of Everything', 'tv', 2015, 'https://image.tmdb.org/t/p/w500/dJxnK0conCaxk3HU4YPb3aQs9UZ.jpg', 'https://image.tmdb.org/t/p/original/hE3hH179vtcaTQ9e2TYJybuG0j5.jpg', 'A biography series based on the life of Zelda Sayre Fitzgerald, the brilliant, beautiful and talented Southern Belle who becomes the original flapper and icon of the wild, flamboyant Jazz Age in the 20s. Z starts before Zelda Fitzgerald meets the unpublished writer F. Scott Fitzgerald and moves through their passionate, turbulent love affair and their marriage-made in heaven, lived out in hell as the celebrity couple of their time.', NULL, NULL, 3.6783, 6.809, 0, 1.02, '2026-08-06 03:21:20', '2026-08-06 03:21:20');
