INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7822, 101733, 'tt2061869', NULL, 'Zombie Ass: Toilet of the Dead', 'ゾンビアス', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/sKJ1uRFB8eFUD40uVOqGl9MXAoY.jpg', 'https://image.tmdb.org/t/p/original/y8heN9YdP7C5s099S7olky4hkOG.jpg', 'Wracked with guilt over her younger sister''s suicide, pretty young karate student Megumi accompanies a group of older friends on a camping trip into the woods, where they''re attacked by feces covered undead.', NULL, NULL, 2.9977, 5.023, 0, 1.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7823, 256742, 'tt3398788', NULL, 'Hotel Inferno', 'Hotel Inferno', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/h6uT2GISxo8jlQkpjqH6WY61z5G.jpg', 'https://image.tmdb.org/t/p/original/ySQ9uB6VqP1M67SzMj5xZbCpRoe.jpg', 'Contract killer Frank Zimosa has been hired for a ridiculously lucrative mission by the rich and powerful Jorge Mistrandia. The objective: kill a couple of people hiding in one of his European hotels. What would look like one of the simplest jobs Frank has ever had is about to turn into a living nightmare. He will soon realize he''s nothing more than prey for Mistrandia and his army of mutated henchmen that have been hiding in the hotel along with an ancient and unstoppable horror.', NULL, NULL, 2.9902, 4.861, 0, 1.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7824, 99117, 'tt2175535', NULL, 'Adam Chaplin', 'Adam Chaplin', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/nEUn35sNCZWkaROnKKZXCOrwsr2.jpg', 'https://image.tmdb.org/t/p/original/vEfBwIp8huLWJElhOP8krbTTK2G.jpg', 'Set in the fictional country of Heaven Valley, the film is the story of a man, Adam, who following the suspicious death of his wife begins to investigate her murder and in doing so, discovers the involvement of local mafia boss: Denny Richards.  Unable to trust the police, corrupt and controlled by Denny, Adam, consumed by anger, summons a demon who offers him superhuman strength and dark powers. The demon follows him during his trip, promising to lead Adam to the door of the murderer if he does everything the demon asks.  This unleashes a bloody war that will bring Adam, the demon on his side, against the police department with all its dark allies. The fight begins and it will be extreme!', NULL, NULL, 1.6358, 6.0, 0, 1.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7825, 442062, 'tt5664636', NULL, 'Goosebumps 2: Haunted Halloween', 'Goosebumps 2: Haunted Halloween', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/t2wy38iiMpB8WsgJi3lYeDnGh2H.jpg', 'https://image.tmdb.org/t/p/original/h5BvesqaxL7V3vl1CmaR8waGyiM.jpg', 'Be careful what you wish for. With their after school junk business, best friends Sonny and Sam hope to find treasure in other people’s trash. But when cleaning out the old Stine house, they open a locked book that frees a supernatural nightmare – Slappy! Now, with the help of Sonny’s sister Sarah, they’re in a race against time to get the sinister dummy and all the creatures he’s brought to life back into the pages before he unleashes total pandemonium!', NULL, NULL, 8.362, 6.091, 0, 11.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7826, 25921, 'tt0280696', NULL, 'Garage Days', 'Garage Days', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/yiV5J3bv6fIugG6oloeLCqSzHuF.jpg', 'https://image.tmdb.org/t/p/original/lSrqv7ZlPgEaBHntKoRVtfqfO6p.jpg', 'The story of a young Sydney band trying to get a foothold in the competitive world of rock n'' roll. After the band''s first gig is a colossal failure, the lead singer takes it upon himself to go out and pursue the most successful rock manager in the country. Meanwhile, the other members of the band continue to deal with the kind of everyday life issues that can ultimately tear a band apart. It may be the dawn of a new millennium, but it''s still a long way to the top if you want to rock n'' roll.', NULL, NULL, 1.1395, 5.5, 0, 11.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7827, 10412, 'tt0105275', NULL, 'Romper Stomper', 'Romper Stomper', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/urE3Jzl3zuz2XUmAq2rXubYn3SD.jpg', 'https://image.tmdb.org/t/p/original/cfGKEah2uUli5HPG1Ry3QK3lwDh.jpg', 'Nazi skinheads in Melbourne take out their anger on local Vietnamese, who are seen as threatening racial purity. Finally the Vietnamese have had enough and confront the skinheads in an all-out confrontation, sending the skinheads running. A woman who is prone to epileptic seizures joins the skins'' merry band, and helps them on their run from justice, but is her affliction also a sign of impurity?', NULL, NULL, 2.6691, 6.542, 0, 11.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
