INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7860, 12403, 'tt0971209', NULL, 'A Perfect Getaway', 'A Perfect Getaway', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/ncuGG0hIlA03dQBJmdoT2LWgodG.jpg', 'https://image.tmdb.org/t/p/original/wQE7BCTo9sdGEG5hywmC0hz8NoZ.jpg', 'For their honeymoon, newlyweds Cliff and Cydney head to the tropical islands of Hawaii. While journeying through the paradisaical countryside the couple encounters Kale and Cleo, two disgruntled hitchhikers and Nick and Gina, two wild but well-meaning spirits who help guide them through the lush jungles. The picturesque waterfalls and scenic mountainsides quickly give way to terror when Cliff and Cydney learn of a grisly murder that occurred nearby and realize that they''re being followed by chance acquaintances that suspiciously fit the description of the killers.', NULL, NULL, 4.7835, 6.328, 0, 10.51, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7861, 846250, 'tt15218000', NULL, 'Fire Island', 'Fire Island', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/2vVUdYoqUX5rK8plxPGERGGjQLI.jpg', 'https://image.tmdb.org/t/p/original/4uwOKYaySkczmZ5C4EO50Ay3IoT.jpg', 'A group of queer best friends gather in the Fire Island Pines for their annual week of love and laughter. However, desires, dramas, drink and drugs push their bonds to the limits.', NULL, NULL, 3.4537, 6.913, 0, 10.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7862, 695089, 'tt9844938', NULL, 'Onoda: 10,000 Nights in the Jungle', 'Onoda, 10 000 nuits dans la jungle', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/tKzFwiEm86AVRsefgqODTBjjh98.jpg', 'https://image.tmdb.org/t/p/original/6Ogax4OJwTmY69cN2u0laFdXU15.jpg', 'Japan, 1944. Trained for intelligence work, Hiroo Onoda, 22 years old, discovers a philosophy contrary to the official line: no suicide; stay alive whatever happens; the mission is more important than anything else. Sent to Lubang, a small island in the Philippines where the Americans are about to land, this role will be to wage a guerrilla war until the return of the Japanese troops. The Empire will surrender soon after; Onoda, 10,000 days later.', NULL, NULL, 2.5621, 7.1, 0, 10.51, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7863, 34851, 'tt1424381', NULL, 'Predators', 'Predators', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/wdniP8NDaJIydi1hMxhpbJMUfr6.jpg', 'https://image.tmdb.org/t/p/original/yVSgw4UyXWg0Edl7KMehdhhgIwL.jpg', 'A group of cold-blooded killers find themselves trapped on an alien planet to be hunted by extraterrestrial Predators.', NULL, NULL, 10.9301, 6.3, 0, 9.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7864, 90259, 'tt10482370', NULL, 'The Third Day', 'The Third Day', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/cW3xE7FKgkXRE1RdZyvUJIoDBFg.jpg', 'https://image.tmdb.org/t/p/original/jIGB53Yto6xOFrFJoOjGKQ9V0ak.jpg', 'A unique story told over two distinct halves, "Summer" follows Sam, a man drawn to a mysterious island off the British coast where he encounters a group of islanders set on preserving their traditions at any cost. "Winter" follows Helen, a strong-willed outsider who comes to the island seeking answers, but whose arrival precipitates a fractious battle to decide its fate.', NULL, NULL, 15.5875, 6.469, 0, 10.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7865, 2303, 'tt0062568', NULL, 'Hawaii Five-O', 'Hawaii Five-O', 'tv', 1968, 'https://image.tmdb.org/t/p/w500/8iFAlqhfY1D0ithTrfKTxObPlUH.jpg', 'https://image.tmdb.org/t/p/original/9as2hYKrhbKWj4ePtFMftQfEsEX.jpg', 'Hawaii Five-O is an American police procedural drama series produced by CBS Productions and Leonard Freeman. Set in Hawaii, the show originally aired for 12 seasons from 1968 to 1980, and continues in reruns. Jack Lord portrayed Detective Lieutenant Steve McGarrett, the head of a special state police task force which was based on an actual unit that existed under martial law in the 1940s. The theme music composed by Morton Stevens became especially popular. Many episodes would end with McGarrett instructing his subordinate to "Book ''em, Danno!", sometimes specifying a charge such as "murder one".', NULL, NULL, 41.1096, 7.182, 0, 9.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7866, 11365, 'tt0120514', NULL, 'Wilde', 'Wilde', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/66ieZHIIOkeQAjAi4ekFpcCLozA.jpg', 'https://image.tmdb.org/t/p/original/8WquHvFVBq9jtfRUUOzMVJBzNW4.jpg', 'Oscar Wilde is a married playwright who has occasionally indulged his weakness for male suitors. After much toil, Wilde debuts ''The Importance of Being Earnest'' in London, and a chat at the theatre with Lord Alfred ''Bosie'' Douglas leads to a full-fledged romance. However, this affair leads to a legal dispute with Lord Alfred''s oppressive father, the Marquess of Queensberry, and, given the local anti-gay laws, Wilde is jailed. Wilde''s vast intellect helps him survive until he regains his freedom.', NULL, NULL, 3.4264, 6.578, 0, 1.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7867, 997113, 'tt27953589', NULL, 'Hedda', 'Hedda', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/ecflk7AZf0ij205yDswjlvdxlCO.jpg', 'https://image.tmdb.org/t/p/original/cKZcDKawR79igCgDMSXlpkn8hLR.jpg', 'Hedda Gabler finds herself torn between the lingering ache of a past love and the quiet suffocation of her present life. Over the course of one charged night, long-repressed desires and hidden tensions erupt—pulling her and everyone around her into a spiral of manipulation, passion, and betrayal.', NULL, NULL, 4.0344, 5.47, 0, 1.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7868, 10399, 'tt0178737', NULL, 'Mansfield Park', 'Mansfield Park', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/4l6KP9BSU1QgSgj9cjpeS3Bfhsr.jpg', 'https://image.tmdb.org/t/p/original/w3jB1liVZioKssQ9V18mEZaTG9V.jpg', 'Fanny Price is sent to live with her wealthy relatives, the Bertrams, where she is treated poorly by most except her cousin Edmund. Her life is complicated by the arrival of the worldly Mary and Henry Crawford.', NULL, NULL, 2.1937, 6.694, 0, 1.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7869, 11024, 'tt0331632', NULL, 'Scooby-Doo 2: Monsters Unleashed', 'Scooby-Doo 2: Monsters Unleashed', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/5BrXCJrs22bR5KR6mLHluYo6y4m.jpg', 'https://image.tmdb.org/t/p/original/m8y7OjvCBLmJfG6CIb5gpXFSLec.jpg', 'A masked villain wreaks mayhem on the city of Coolsville with a monster machine that creates real-life versions of Mystery Inc.''s former foes like The 10,000 Volt Ghost, The Cotton Candy Glob, The Skelemen and The Pterodactyl Ghost. Fred, Daphne, Shaggy, Velma and Scooby-Doo launch an investigation into the monster outbreak that leaves Shaggy and Scooby questioning their roles in Mystery Inc. Eager to prove their detective skills, the ever-ravenous duo comes up with a secret plan to solve the mystery all by themselves. Can the gang unravel their most challenging case?', NULL, NULL, 5.3041, 6.108, 0, 1.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
