INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7873, 1494809, NULL, NULL, 'Weeping Rocks', 'Weeping Rocks', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/hC2QioP4gONeWzEE4sGuP0ekMqN.jpg', 'https://image.tmdb.org/t/p/original/nN86dXBobJsd3jCEETQTiE7rreu.jpg', 'Weeping Rocks follows Art, an entomologist nearing the end of his life, who has spent over five decades walking the same ten trails counting butterflies. His eccentric practice has uncovered patterns of environmental decline that went unnoticed for years. As time reshapes the landscape and species fade, Art’s journey becomes a meditation on mortality, change, and the beauty of what remains.', NULL, NULL, 1.9755, 0.0, 0, 8.03, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
