INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7881, 4232, 'tt0054572', NULL, 'Top Cat', 'Top Cat', 'tv', 1961, 'https://image.tmdb.org/t/p/w500/hnWYwPE7nwqAD1OGLEEXyML5LaH.jpg', 'https://image.tmdb.org/t/p/original/82czKnq7CcHaGjNSkxlHLwanE2k.jpg', 'Top Cat, known as T.C. to his alley cat friends, is a mischievous prankster who lives in a trash can in the alley ways of New York City. He and his alley-cat cohorts think of get rich schemes and assorted pranks which are mostly involving and aimed at Officer Dibble, their nemesis and friend. T.C. manages to get out of his tight situations with hilarity and charm and even helps Dibble on occasion who is underscored by his overbearing sergeant...', NULL, NULL, 6.9115, 7.531, 0, 7.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
