INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7883, 18890, 'tt0108526', NULL, 'We''re Back! A Dinosaur''s Story', 'We''re Back! A Dinosaur''s Story', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/iyFmhYlioe3PDZjSKWtcIhu5R02.jpg', 'https://image.tmdb.org/t/p/original/6pbIOpnWFAO42JgZhuNUdMEUxi8.jpg', 'Captain New Eyes travels back in time and feeds dinosaurs his Brain Grain cereal, which makes them intelligent and non-violent. They agree to go to the "Middle Future" in order to grant the wishes of children in New York City. They are to meet Dr. Bleeb of the Museum of Natural History, but get sidetracked with their new children friends and run into the Captain''s evil brother, Professor Screweyes.', NULL, NULL, 3.0984, 6.1, 0, 8.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
