INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7886, 16094, 'tt0099800', NULL, 'House Party', 'House Party', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/hmUsEUI7RdgvTznkLCNSOHnjU4O.jpg', 'https://image.tmdb.org/t/p/original/vBaBRMCYiYRHHPKDl765HD42n9O.jpg', 'Young Kid has been invited to a party at his friend Play''s house. But after a fight at school, Kid''s father grounds him. None the less, Kid sneaks out when his father falls asleep. But Kid doesn''t know that three of the thugs at school have decided to give him a lesson in behavior.', NULL, NULL, 6.1046, 6.408, 0, 7.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7887, 15480, 'tt0091594', NULL, 'Müllers Büro', 'Müllers Büro', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/sB9A8ztFsbvJeULr4v4I83V4zdU.jpg', 'https://image.tmdb.org/t/p/original/egKRAW3y8YHNiTeu7fWUjQ8wfMv.jpg', 'Musical film-noir parody about Max Müller, an underemployed private detective who is asked by his beautiful but secretive client, Ingrid Bergmann to look for her disappeared fiancé. Together with his assistant Larry he combs the underworld and little by little it becomes clear that his mysterious client is not what she seems to be.', NULL, NULL, 0.5104, 5.667, 0, 6.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
