INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7889, 15653, 'tt0208185', NULL, 'An Extremely Goofy Movie', 'An Extremely Goofy Movie', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/qr5Q3S7HC16XHQBqE4ZsJJvgUDU.jpg', 'https://image.tmdb.org/t/p/original/2XoHSRRhwSdv42suJMJBgEyWy5b.jpg', 'It''s all extreme sports and a life of freedom as Max sets off for college -- but Goofy misses Max so much he loses his job and goes to finish college alongside Max and his friends. But as Goofy tries to get closer to Max, both must go to the extreme to learn how to live their own lives together.', NULL, NULL, 4.9423, 6.448, 0, 9.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7890, 5191, 'tt0108909', NULL, 'RoboCop: The Series', 'RoboCop: The Series', 'tv', 1994, 'https://image.tmdb.org/t/p/w500/lKPeX5a04E1qrzAVeI43ocfinM.jpg', 'https://image.tmdb.org/t/p/original/ayfwBr79hFnDuff15mm59ZRbU0W.jpg', 'RoboCop: The Series is a 1994 television series based on the film of the same name. It stars Richard Eden as the title character. Made to appeal primarily to children and young teenagers, it lacks the graphic violence that was the hallmark of RoboCop and RoboCop 2. RoboCop has several non-lethal alternatives to killing criminals, which ensures that certain villains can be recurring. The OCP Chairman and his corporation are treated as simply naïve and ignorant, in contrast to their malicious and immoral behavior from the second film onward.', NULL, NULL, 5.7709, 6.367, 0, 8.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7891, 13084, 'tt0128886', NULL, 'Night Man', 'Night Man', 'tv', 1997, 'https://image.tmdb.org/t/p/w500/d5rE9WSSsRTuvfjRb9dOpnIMAOJ.jpg', 'https://image.tmdb.org/t/p/original/38UpV8o9cbXtj4gwZrCHSVb9che.jpg', 'Night Man is an American action/adventure/sci-fi series that aired in syndication from September 15, 1997 to May 17, 1999. The series is loosely based on a comic book published by Malibu Comics and was created by Steve Englehart and developed for television by Glen A. Larson.

It stars Matt McColm as the title character, a superhero whose real name was Johnny Domino, a saxophonist. Englehart would write three episodes of the series. Night Man is also one of the few series to cross over with characters from Larson''s previous series: in the episode "Manimal", Johnny allies with Professor Jonathan Chase, the star of the short-lived 1980s'' series Manimal.', NULL, NULL, 4.6776, 6.5, 0, 8.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
