INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7893, 13670, 'tt0103414', NULL, 'Fish Police', 'Fish Police', 'tv', 1992, 'https://image.tmdb.org/t/p/w500/dW7N0oEfYQBMwJE6MyFsAZWUtkl.jpg', 'https://image.tmdb.org/t/p/original/wGaQ2p9cdXcfEkUkXc9picN9pCv.jpg', 'Fish Police is a comic book series by cartoonist Steve Moncuse. The plot centers on law and crime in a fictional underwater metropolis with the protagonist, Inspector Gill, trying to solve various, often Mafia-related, crimes while avoiding being seduced by the buxom Angel Jones. The comic featured several marine species as its characters, while the plots and dialogue were reminiscent of film noir.

Original Fish Police stories were published from 1985 to 1991, and featured the early work of Sam Kieth as inker.', NULL, NULL, 2.7555, 5.727, 0, 8.01, '2026-08-06 03:21:21', '2026-08-06 03:21:21');
