UPDATE "recommendations" SET "tmdb_id"=201085, "imdb_id"='tt2554274', "igdb_id"=NULL, "title"='Crimson Peak', "original_title"='Crimson Peak', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/f9TOb5anVwZeSbYjU1qNxPk3KUk.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nQQIUwEEqa6sjPvnqcGbjJxbdit.jpg', "overview"='In the aftermath of a family tragedy, an aspiring author is torn between love for her childhood friend and the temptation of a mysterious outsider. Trying to escape the ghosts of her past, she is swept away to a house that breathes, bleeds… and remembers.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.5712, "vote_average"=6.7, "is_ambiguous"=0, "evidence_score"=4.37921621621621639e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:21' WHERE "id"=4;
