UPDATE "recommendations" SET "tmdb_id"=8967, "imdb_id"='tt0478304', "igdb_id"=NULL, "title"='The Tree of Life', "original_title"='The Tree of Life', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/l8cwuB5WJSoj4uMAsnzuHBOMaSJ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xq1HIwZq9VbuvMQELAua1nqEkH.jpg', "overview"='The impressionistic story of a Texas family in the 1950s. The film follows the life journey of the eldest son, Jack, through the innocence of childhood to his disillusioned adult years as he tries to reconcile a complicated relationship with his father. Jack finds himself a lost soul in the modern world, seeking answers to the origins and meaning of life while questioning the existence of faith.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.6069, "vote_average"=6.718, "is_ambiguous"=0, "evidence_score"=2.58004761904761892e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=34;
UPDATE "recommendations" SET "tmdb_id"=274854, "imdb_id"='tt1618442', "igdb_id"=NULL, "title"='The Last Witch Hunter', "original_title"='The Last Witch Hunter', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/dS9YdnJkxtKE2PKCSsxTaO7Jpf5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mXmvN6drkdU1PWFF92AGklEVIa3.jpg', "overview"='The modern world holds many secrets, but by far the most astounding is that witches still live among us; vicious supernatural creatures intent on unleashing the Black Death upon the world and putting an end to the human race once and for all. Armies of witch hunters have battled this unnatural enemy for centuries, including Kaulder, a valiant warrior who many years ago slayed the all-powerful Witch Queen, decimating her followers in the process. In the moments right before her death, the Queen cursed Kaulder with immortality, forever separating him from his beloved wife and daughter. Today, Kaulder is the last living hunter who has spent his immortal life tracking down rogue witches, all the while yearning for his long-lost family.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.6492, "vote_average"=6.017, "is_ambiguous"=0, "evidence_score"=4.90644444444444403e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=39;
