UPDATE "recommendations" SET "tmdb_id"=13225, "imdb_id"='tt0104254', "igdb_id"=NULL, "title"='FernGully: The Last Rainforest', "original_title"='FernGully: The Last Rainforest', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/xkJxdeaibcrcsi1XHvT0IuOjdzB.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2GBUz0Z4YyKi2ojHylPIT6yBBl1.jpg', "overview"='When a sprite named Crysta shrinks a human boy, Zak, down to her size, he vows to help the magical fairy folk stop a greedy logging company from destroying their home: the pristine rainforest known as FernGully. Zak and his new friends fight to defend FernGully from lumberjacks — and the vengeful spirit they accidentally unleash after chopping down a magic tree.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.7363, "vote_average"=6.406, "is_ambiguous"=0, "evidence_score"=1.6461666666666666e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=158;
UPDATE "recommendations" SET "tmdb_id"=11236, "imdb_id"='tt0108071', "igdb_id"=NULL, "title"='The Secret Garden', "original_title"='The Secret Garden', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/zf6h5dJ7wVG7LqMO9dhHGHVejzj.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8s7FJ9dHXgeFZdvxfjPmrrJh6EC.jpg', "overview"='A young British girl born and reared in India loses her neglectful parents in an earthquake. She is returned to England to live at her uncle''s castle. Her uncle is very distant due to the loss of his wife ten years before. Neglected once again, she begins exploring the estate and discovers a garden that has been locked and forgotten. Aided by one of the servants'' boys, she begins restoring the garden, and eventually discovers some other secrets of the manor.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.4349, "vote_average"=7.425, "is_ambiguous"=0, "evidence_score"=19.843125, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:21' WHERE "id"=166;
