UPDATE "recommendations" SET "tmdb_id"=37735, "imdb_id"='tt1282140', "igdb_id"=NULL, "title"='Easy A', "original_title"='Easy A', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/v5f1qO6NJnxWgONgkYg21TW39DT.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/30rvmoEBqovm723agDJ3QddWXcY.jpg', "overview"='Olive, an average high school student, sees her below-the-radar existence turn around overnight once she decides to use the school''s gossip grapevine to advance her social standing. Now her classmates are turning against her and the school board is becoming concerned, including her favorite teacher and the distracted guidance counselor. With the support of her hilariously idiosyncratic parents and a little help from a long-time crush, Olive attempts to take on her notorious new identity and crush the rumor mill once and for all.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.2755, "vote_average"=6.8, "is_ambiguous"=0, "evidence_score"=1.03666666666666671e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=654;
