UPDATE "recommendations" SET "tmdb_id"=10096, "imdb_id"='tt0337563', "igdb_id"=NULL, "title"='13 Going on 30', "original_title"='13 Going on 30', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/iNZdSIfhSCMtRILDNyhLn8UKeSG.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ld7UTOGzZSxIMbuYsb6eQ6QdN4h.jpg', "overview"='After total humiliation at her thirteenth birthday party, Jenna Rink wants to just hide until she''s thirty. Thanks to some magic wishing dust, Jenna''s prayer has been answered. With a knockout body, a fabulous wardrobe, an athlete boyfriend, a dream job, and superstar friends, this can''t be a better life. But soon Jenna realizes that adult life isn’t as easy as she hoped for.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.0982, "vote_average"=6.777, "is_ambiguous"=0, "evidence_score"=8.46142857142857174e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=667;
UPDATE "recommendations" SET "tmdb_id"=9603, "imdb_id"='tt0112697', "igdb_id"=NULL, "title"='Clueless', "original_title"='Clueless', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/8AwVTcgpTnmeOs4TdTWqcFDXEsA.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/65d0MccsiRSPTVicregKQL8owoo.jpg', "overview"='Shallow, rich and socially successful Cher is at the top of her Beverly Hills high school''s pecking scale. Seeing herself as a matchmaker, Cher first coaxes two teachers into dating each other. Emboldened by her success, she decides to give hopelessly klutzy new student Tai a makeover. When Tai becomes more popular than she is, Cher realizes that her disapproving ex-stepbrother was right about how misguided she was -- and falls for him.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.7261, "vote_average"=7.25, "is_ambiguous"=0, "evidence_score"=1.19936363636363623e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=668;
