UPDATE "recommendations" SET "tmdb_id"=5548, "imdb_id"='tt0093870', "igdb_id"=NULL, "title"='RoboCop', "original_title"='RoboCop', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/hHtOgGb3NihlyRATHlKPaFApbrd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xcaX6BZ1JUPSVMH2gBkWIckLLaA.jpg', "overview"='In a violent, near-apocalyptic Detroit, evil corporation Omni Consumer Products wins a contract from the city government to privatize the police force. To test their crime-eradicating cyborgs, the company leads street cop Alex Murphy into an armed confrontation with crime lord Boddicker so they can use his body to support their untested RoboCop prototype. But when RoboCop learns of the company''s nefarious plans, he turns on his masters.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.3779, "vote_average"=7.364, "is_ambiguous"=0, "evidence_score"=12.968, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=777;
