UPDATE "recommendations" SET "tmdb_id"=411, "imdb_id"='tt0363771', "igdb_id"=NULL, "title"='The Chronicles of Narnia: The Lion, the Witch and the Wardrobe', "original_title"='The Chronicles of Narnia: The Lion, the Witch and the Wardrobe', "media_type"='movie', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/iREd0rNCjYdf5Ar0vfaW32yrkm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/tuDhEdza074bA497bO9WFEPs6O6.jpg', "overview"='Siblings Lucy, Edmund, Susan and Peter step through a magical wardrobe and find the land of Narnia. There, they discover a charming, once peaceful kingdom that has been plunged into eternal winter by the evil White Witch, Jadis. Aided by the wise and magnificent lion, Aslan, the children lead Narnia into a spectacular, climactic battle to be free of the Witch''s glacial powers forever.', "external_url"=NULL, "platforms"=NULL, "popularity"=21.5964, "vote_average"=7.1, "is_ambiguous"=0, "evidence_score"=18.515, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=807;
