UPDATE "recommendations" SET "tmdb_id"=9064, "imdb_id"='tt0095294', "igdb_id"=NULL, "title"='Hellbound: Hellraiser II', "original_title"='Hellbound: Hellraiser II', "media_type"='movie', "release_year"=1988, "poster_url"='https://image.tmdb.org/t/p/w500/auPOq1wgZuYSaADejOskBKG6fuV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pl5OzUABUK5AgAsMlQg2VyybRHL.jpg', "overview"='Now confined to a mental hospital, young Kirsty insists her supposedly dead father is actually stuck in Hell following his wife’s betrayal. Few believe the young woman’s lurid stories aside from the thrill-seeking Dr. Channard. Kirsty is undeterred and, with the help of a fellow patient, heads to Hell for a rescue.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.4682, "vote_average"=6.414, "is_ambiguous"=0, "evidence_score"=13.51, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:21' WHERE "id"=819;
UPDATE "recommendations" SET "tmdb_id"=841, "imdb_id"='tt0087182', "igdb_id"=NULL, "title"='Dune', "original_title"='Dune', "media_type"='movie', "release_year"=1984, "poster_url"='https://image.tmdb.org/t/p/w500/4kJmUCE7mkVJjXa7A0g2rY4IGTm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5wJ2tckpvwcxGCAgZiccodwEJpf.jpg', "overview"='In the year 10,191, the most precious substance in the universe is the spice Melange. The spice extends life. The spice expands consciousness. The spice is vital to space travel.  The spice exists on only one planet in the entire universe, the vast desert planet Arrakis, also known as Dune.  Its native inhabitants, the Fremen, have long held a prophecy that a man would come, a messiah who would lead them to true freedom.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.6554, "vote_average"=6.186, "is_ambiguous"=0, "evidence_score"=1.42583333333333328e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=821;
UPDATE "recommendations" SET "tmdb_id"=65086, "imdb_id"='tt1596365', "igdb_id"=NULL, "title"='The Woman in Black', "original_title"='The Woman in Black', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nghQnDZE4EsQJ4J4zxR3UqItTpO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jJ3yFKs6xeVGxtmm7GXZYQ3XAvz.jpg', "overview"='The story follows a young lawyer, Arthur Kipps, who is ordered to travel to a remote village and sort out a recently deceased client’s papers. As he works alone in the client’s isolated house, Kipps begins to uncover tragic secrets, his unease growing when he glimpses a mysterious woman dressed only in black. Receiving only silence from the locals, Kipps is forced to uncover the true identity of the Woman in Black on his own, leading to a desperate race against time when he discovers her true identity.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.9988, "vote_average"=6.144, "is_ambiguous"=0, "evidence_score"=1.68584615384615368e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:21' WHERE "id"=849;
