UPDATE "recommendations" SET "tmdb_id"=10227, "imdb_id"='tt0062136', "igdb_id"=NULL, "title"='PlayTime', "original_title"='PlayTime', "media_type"='movie', "release_year"=1967, "poster_url"='https://image.tmdb.org/t/p/w500/kQOrS0DLUXYsqPMedM2G6NJcJBq.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pKX8G6IN8ZCRvKeHh6ctqoHZl0K.jpg', "overview"='Clumsy Monsieur Hulot finds himself perplexed by the intimidating complexity of a gadget-filled Paris. He attempts to meet with a business contact but soon becomes lost. His roundabout journey parallels that of an American tourist, and as they weave through the inventive urban environment, they intermittently meet, developing an interest in one another. They eventually get together at a chaotic restaurant, along with several other quirky characters.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.7514, "vote_average"=7.7, "is_ambiguous"=0, "evidence_score"=10.69, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=867;
UPDATE "recommendations" SET "tmdb_id"=185, "imdb_id"='tt0066921', "igdb_id"=NULL, "title"='A Clockwork Orange', "original_title"='A Clockwork Orange', "media_type"='movie', "release_year"=1971, "poster_url"='https://image.tmdb.org/t/p/w500/4sHeTAp65WrSSuc05nRBKddhBxO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nLFxvLokHe3bQmrmAfljIfax2jQ.jpg', "overview"='In a near-future Britain, young Alexander DeLarge and his pals get their kicks beating and raping anyone they please. When not destroying the lives of others, Alex swoons to the music of Beethoven. The state, eager to crack down on juvenile crime, gives an incarcerated Alex the option to undergo an invasive procedure that''ll rob him of all personal agency. In a time when conscience is a commodity, can Alex change his tune?', "external_url"=NULL, "platforms"=NULL, "popularity"=13.2023, "vote_average"=8.175, "is_ambiguous"=0, "evidence_score"=20.721875, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=871;
UPDATE "recommendations" SET "tmdb_id"=196055, "imdb_id"='tt37663169', "igdb_id"=NULL, "title"='The Wall of the Eye', "original_title"='眼の壁', "media_type"='tv', "release_year"=2022, "poster_url"='https://image.tmdb.org/t/p/w500/pJuqUdziI4Mj4vKMq4PmT3LrfXs.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/thfBDR9b0rYfrCRELoq6DXGxtfJ.jpg', "overview"='In 1990, Hagizaki Tatsuo, the accounting department chief of Ukishima Electric Works, was busy negotiating on getting a loan together with Sekino, the company''s general manager. However, just as they were about to get the funds, Sekino was involved in a 200 million yen fraud and he later disappeared with the loan. The company decides to cover up the incident to protect its image, but Hagizaki wants to get to the bottom of the matter with the help of his newspaper reporter friend, Muraki. Hagizaki later notices that the case becomes darker and darker as he continues to investigate. He then meets a beautiful woman, Uezaki Etsuko, whom he believes hold the key to the entire incident.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.1801, "vote_average"=8.5, "is_ambiguous"=0, "evidence_score"=1.09699999999999988e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=886;
