UPDATE "recommendations" SET "tmdb_id"=28276, "imdb_id"='tt0053134', "igdb_id"=NULL, "title"='Good Morning', "original_title"='お早よう', "media_type"='movie', "release_year"=1959, "poster_url"='https://image.tmdb.org/t/p/w500/dXy2LFsE0VlHlHJU3SLBdJgrzEq.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qH9wiXnx9mU9kNGCH1exaey9CqU.jpg', "overview"='A lighthearted take on director Yasujiro Ozu’s perennial theme of the challenges of inter­generational relationships, Good Morning tells the story of two young boys who stop speaking in protest after their parents refuse to buy a television set. Ozu weaves a wealth of subtle gags through a family portrait as rich as those of his dramatic films, mocking the foibles of the adult world through the eyes of his child protagonists. Shot in stunning color and set in a suburb of Tokyo where housewives gossip about the neighbors’ new washing machine and unemployed husbands look for work as door-to-door salesmen, this charming comedy refashions Ozu’s own silent classic I Was Born, But . . . to gently satirize consumerism in postwar Japan.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.3049, "vote_average"=7.714, "is_ambiguous"=0, "evidence_score"=9.01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=1814;
UPDATE "recommendations" SET "tmdb_id"=37797, "imdb_id"='tt0113824', "igdb_id"=NULL, "title"='Whisper of the Heart', "original_title"='耳をすませば', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/5FROLD8zpWFs9ja7aYho1uOMJHg.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rphor0XQcYO4CQoQ6auaQm3UPap.jpg', "overview"='Shizuku lives a simple life, dominated by her love for stories and writing. One day she notices that all the library books she has have been previously checked out by the same person: "Seiji Amasawa."', "external_url"=NULL, "platforms"=NULL, "popularity"=6.4139, "vote_average"=7.945, "is_ambiguous"=0, "evidence_score"=1.33833333333333346e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=1817;
UPDATE "recommendations" SET "tmdb_id"=80, "imdb_id"='tt0381681', "igdb_id"=NULL, "title"='Before Sunset', "original_title"='Before Sunset', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/4sW5XH9ZfYXpvFzev00S1IGAEbg.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/tcZi0LQc5iu2u6i5aOWyj9NBBvl.jpg', "overview"='Nine years later, Jesse travels across Europe giving readings from a book he wrote about the night he spent in Vienna with Celine. After his reading in Paris, Celine finds him, and they spend part of the day together before Jesse has to again leave for a flight. They are both in relationships now, and Jesse has a son, but as their strong feelings for each other start to return, both confess a longing for more.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.0638, "vote_average"=7.803, "is_ambiguous"=0, "evidence_score"=10.43875, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=1820;
UPDATE "recommendations" SET "tmdb_id"=12429, "imdb_id"='tt0876563', "igdb_id"=NULL, "title"='Ponyo', "original_title"='崖の上のポニョ', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/yp8vEZflGynlEylxEesbYasc06i.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/shqLeIkqPAAXM8iT6wVDiXUYz1p.jpg', "overview"='When Sosuke, a young boy who lives on a clifftop overlooking the sea, rescues a stranded goldfish named Ponyo, he discovers more than he bargained for. Ponyo is a curious, energetic young creature who yearns to be human, but even as she causes chaos around the house, her father, a powerful sorcerer, schemes to return Ponyo to the sea.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.1497, "vote_average"=7.762, "is_ambiguous"=0, "evidence_score"=6.84, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=1824;
