UPDATE "recommendations" SET "tmdb_id"=2000, "imdb_id"='tt0068182', "igdb_id"=NULL, "title"='Aguirre, the Wrath of God', "original_title"='Aguirre, der Zorn Gottes', "media_type"='movie', "release_year"=1972, "poster_url"='https://image.tmdb.org/t/p/w500/zU1FLiGJw3m3iFrakwA0SzFvIPV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/kfSZaOr9ApNR52gWKlpXHD0id0W.jpg', "overview"='A few decades after the destruction of the Inca Empire, a Spanish expedition led by the infamous Aguirre leaves the mountains of Peru and goes down the Amazon River in search of the lost city of El Dorado. When great difficulties arise, Aguirre’s men start to wonder whether their quest will lead them to prosperity or certain death.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.4752, "vote_average"=7.433, "is_ambiguous"=0, "evidence_score"=1.22385714285714293e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=1842;
UPDATE "recommendations" SET "tmdb_id"=10235, "imdb_id"='tt0029850', "igdb_id"=NULL, "title"='Alexander Nevsky', "original_title"='Александр Невский', "media_type"='movie', "release_year"=1938, "poster_url"='https://image.tmdb.org/t/p/w500/lsTJYStIsnddwioD1L4FEmwj4Cx.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/izg3sL4nJwehVsUy1mn1sLOmvuK.jpg', "overview"='When German knights invade Russia, Prince Alexander Nevsky must rally his people to resist the formidable force. After the Teutonic soldiers take over an eastern Russian city, Alexander stages his stand at Novgorod, where a major battle is fought on the ice of frozen Lake Chudskoe. While Alexander leads his outnumbered troops, two of their number, Vasili and Gavrilo, begin a contest of bravery to win the hand of a local maiden.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8379, "vote_average"=7.0, "is_ambiguous"=0, "evidence_score"=1.2673333333333332e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=1854;
UPDATE "recommendations" SET "tmdb_id"=9476, "imdb_id"='tt0183790', "igdb_id"=NULL, "title"='A Knight''s Tale', "original_title"='A Knight''s Tale', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/srb1XnrlDZHcdpjBKqUu4qAzxKU.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/gkT737kgnmI6jZyXbUBJRwVbGkW.jpg', "overview"='William Thatcher, a knight''s peasant apprentice, gets a chance at glory when the knight dies suddenly mid-tournament. Posing as a knight himself, William won''t stop until he''s crowned tournament champion—assuming matters of the heart don''t get in the way.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.7255, "vote_average"=6.882, "is_ambiguous"=0, "evidence_score"=1.57972727272727286e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=1859;
UPDATE "recommendations" SET "tmdb_id"=895, "imdb_id"='tt0060107', "igdb_id"=NULL, "title"='Andrei Rublev', "original_title"='Андрей Рублёв', "media_type"='movie', "release_year"=1966, "poster_url"='https://image.tmdb.org/t/p/w500/jUihkn16SwPPIjuOyo6orHWUep6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jqha8JCXm0aJ5SJ03Jd0JmGgWRs.jpg', "overview"='An expansive Russian drama, this film focuses on the life of revered religious icon painter Andrei Rublev. Drifting from place to place in a tumultuous era, the peace-seeking monk eventually gains a reputation for his art. But after Rublev witnesses a brutal battle and unintentionally becomes involved, he takes a vow of silence and spends time away from his work. As he begins to ease his troubled soul, he takes steps towards becoming a painter once again.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.4606, "vote_average"=7.935, "is_ambiguous"=0, "evidence_score"=1.60384615384615401e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=1860;
UPDATE "recommendations" SET "tmdb_id"=62177, "imdb_id"='tt1217209', "igdb_id"=NULL, "title"='Brave', "original_title"='Brave', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/1XAuDtMWpL0sYSFK0R6EZate2Ux.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qx9ts2hBYJrkIQxhryitxnLlm2u.jpg', "overview"='In the mystical Scottish Highlands, Merida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Merida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Merida seeks out an eccentric old Wise Woman and is granted an ill-fated wish. Also figuring into Merida''s quest — and serving as comic relief — are the kingdom''s three lords: the enormous Lord MacGuffin, the surly Lord Macintosh, and the disagreeable Lord Dingwall.', "external_url"=NULL, "platforms"=NULL, "popularity"=17.7813, "vote_average"=7.0, "is_ambiguous"=0, "evidence_score"=1.57191666666666662e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:21' WHERE "id"=1862;
UPDATE "recommendations" SET "tmdb_id"=762, "imdb_id"='tt0071853', "igdb_id"=NULL, "title"='Monty Python and the Holy Grail', "original_title"='Monty Python and the Holy Grail', "media_type"='movie', "release_year"=1975, "poster_url"='https://image.tmdb.org/t/p/w500/7nTkHjETdGMYK1phHwDbPsrzbYl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1KgXxv6tHXOnakqYvMPvFwYKWiw.jpg', "overview"='King Arthur, accompanied by his squire, recruits his Knights of the Round Table, including Sir Bedevere the Wise, Sir Lancelot the Brave, Sir Robin the Not-Quite-So-Brave-As-Sir-Lancelot and Sir Galahad the Pure. On the way, Arthur battles the Black Knight who, despite having had all his limbs chopped off, insists he can still fight. They reach Camelot, but Arthur decides not  to enter, as "it is a silly place".', "external_url"=NULL, "platforms"=NULL, "popularity"=8.0972, "vote_average"=7.803, "is_ambiguous"=0, "evidence_score"=11.28, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=1863;
