UPDATE "recommendations" SET "tmdb_id"=49637, "imdb_id"='tt1396227', "igdb_id"=NULL, "title"='The Wild and Wonderful Whites of West Virginia', "original_title"='The Wild and Wonderful Whites of West Virginia', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/7EQQsuK1Hk1zcoBlNBKfU41aS39.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2S0Kk3cMPE2CX0vEJ6Fp5OjPZgI.jpg', "overview"='Produced by Johnny Knoxville and Jeff Tremaine for MTV and Dickhouse Productions, The Wild and Wonderful Whites of West Virginia is a documentary about the renowned West Virginia outlaw Jesco White and his eccentric backwoods family. In addition to getting in trouble with the law, the Whites, who live deep within Appalachia, uphold a time-honored dancing style, even as they contend with poverty, drugs and other issues. Alternately humorous and sad, the movie is an unflinching look at life on the criminal margins of rural mountain culture.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.7399, "vote_average"=6.74, "is_ambiguous"=0, "evidence_score"=12.68, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-06 03:21:20' WHERE "id"=2575;
