UPDATE "recommendations" SET "tmdb_id"=52886, "imdb_id"='tt0092732', "igdb_id"=NULL, "title"='Castaway', "original_title"='Castaway', "media_type"='movie', "release_year"=1986, "poster_url"='https://image.tmdb.org/t/p/w500/mphJksO1hwAEmcMawNFvRZJJ5n.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/bpBcgPYG3PRjzxdBCuli8jeEslw.jpg', "overview"='Middle-aged Gerald Kingsland advertises in a London paper for a female companion to spend a year with him on a desert island. Young Lucy Irving takes a chance on contacting him, but once on the island, things prove a lot less idyllic than in the movies. Gradually, it becomes clear that it is Lucy who has the desire and the strength to try and see the year through.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.052, "vote_average"=6.28, "is_ambiguous"=0, "evidence_score"=1.2673333333333332e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-06 03:21:21' WHERE "id"=3452;
