UPDATE "recommendations" SET "tmdb_id"=17287, "imdb_id"='tt0462485', "igdb_id"=NULL, "title"='Poultrygeist: Night of the Chicken Dead', "original_title"='Poultrygeist: Night of the Chicken Dead', "media_type"='movie', "release_year"=2006, "poster_url"='https://image.tmdb.org/t/p/w500/vSeehH4s274kdZXEMKnPE2tlqco.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jtnFTuRejS925CJkXf3MNCqtT8n.jpg', "overview"='When the American Chicken Bunker, a military themed fast food restaurant, builds its latest chain restaurant on the site of an ancient Native American burial ground, the displaced spirits take revenge on unsuspecting diners and transform them into chicken zombies! Now, it’s up to a dimwitted counter boy, his collegiate lesbian ex-girlfriend and a burqa-wearing fry cook to put an end to the foul feathered menace once and for all.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.4911, "vote_average"=5.861, "is_ambiguous"=0, "evidence_score"=2.015, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-06 03:21:21' WHERE "id"=4152;
