UPDATE "recommendations" SET "tmdb_id"=34791, "imdb_id"='tt0985344', "igdb_id"=NULL, "title"='Claymore', "original_title"='クレイモア', "media_type"='tv', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/rQt8X4kjBxah0laGwUVJISf1086.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9345bFQXPCyIJLQemkpI5zFJCOp.jpg', "overview"='When a shapeshifting demon with a thirst for human flesh, known as "youma," arrives in Raki''s village, a lone woman with silver eyes walks into town with only a sword upon her back. She is a "Claymore," a being manufactured as half-human and half-youma, for the express purpose of exterminating these monsters. After Raki''s family is killed, the Claymore saves his life, but he is subsequently banished from his home. With nowhere else to go, Raki finds the Claymore, known as Clare, and decides to follow her on her journeys.

As the pair travel from town to town, defeating youma along the way, more about Clare''s organization and her fellow warriors comes to light. With every town cleansed and every demon destroyed, they come closer to the youma on which Clare has sought vengeance ever since she chose to become a Claymore.', "external_url"=NULL, "platforms"=NULL, "popularity"=14.4395, "vote_average"=8.172, "is_ambiguous"=0, "evidence_score"=2.01, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-06 03:21:20' WHERE "id"=5032;
