UPDATE "recommendations" SET "tmdb_id"=11497, "imdb_id"='tt0096787', "igdb_id"=NULL, "title"='All Dogs Go to Heaven', "original_title"='All Dogs Go to Heaven', "media_type"='movie', "release_year"=1989, "poster_url"='https://image.tmdb.org/t/p/w500/nmWh1NglDinfkHD9zCNqGWyhl7Q.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/haJ6SsjxfhSRG61LMy4QJWxCNAb.jpg', "overview"='When a casino-owning dog named Charlie is murdered by his rival Carface, he finds himself in Heaven. Wanting to get back at his killer, he cons his way back to the living with the warning that doing so damns him to Hell. Once back, he teams with his old partner, Itchy, to prep his retaliation. He stumbles upon an orphan girl who can talk to the animals, thus allowing him to get the inside info on the races to ensure his wins to finance his plans. However, all the while, he is still haunted by nightmares of what''s waiting for him on the other side unless he can prove that he is worthy of Heaven again.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.0755, "vote_average"=6.835, "is_ambiguous"=0, "evidence_score"=5.76, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-06 03:21:21' WHERE "id"=6504;
