UPDATE "recommendations" SET "tmdb_id"=466523, "imdb_id"='tt1712127', "igdb_id"=NULL, "title"='Malice in Wonderland: The Dolls Movie', "original_title"='Malice in Wonderland: The Dolls Movie', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/fi89eoCkEZ4RxjCRwK8IpntJbFW.jpg', "backdrop_url"=NULL, "overview"='This bawdy comedic film parodies the classics Alice in Wonderland, Wizard of Oz and Mommie Dearest. In the grand tradition of Shakespeare, all the roles are played by men (except two). The story opens with the hiring of a Joan Crawford look-a-like from Nanny Dearest, Incorporated. The relationship turns comedic tables with the cigarette smoking Alice in service to the demanding nanny. In a fit, ''Nanny Dearest'' flushes Alice and her rabbit down the toilet. Alice is deposited in Wonderland, where she meets a multitude of strange characters while pursuing the rabbit; ending at the Red Queen''s Orgy. Alice barely makes it out of Wonderland with her head. Awakening in bed with Nanny Dearest at her side, Alice realizes she has learned much from Nanny.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.4319, "vote_average"=1.0, "is_ambiguous"=0, "evidence_score"=3.02666666666666683e+00, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-06 03:21:20' WHERE "id"=6942;
